import{encrypt,decrypt}from"./content_encryption.js";import{encode as b64u}from"../util/base64url.js";export async function wrap(t,r,n,e){const c=t.slice(0,7),i=await encrypt(c,n,r,e,new Uint8Array);return{encryptedKey:i.ciphertext,iv:b64u(i.iv),tag:b64u(i.tag)}}export async function unwrap(t,r,n,e,c){const i=t.slice(0,7);return decrypt(i,r,n,e,c,new Uint8Array)}